const loans=[['housing','Housing loan','A considered path to owning a home.'],['mortgage','Mortgage loan','Explore borrowing secured against property.'],['lic-nsc','Loan against LIC / NSC','Learn about lending against eligible savings instruments.'],['bank-fdr','Loan against bank FDR','Explore credit secured against a fixed deposit.'],['gold','Loan against gold','A lending option secured by eligible gold.'],['vehicle','Loan against vehicle','Financing support for your next vehicle.'],['education','Education loan','Support for education and future plans.'],['cash-credit','Cash credit facility','A flexible working capital facility.'],['overdraft-fdr','Overdraft against FDR','Access funds secured against a fixed deposit.'],['overdraft-property','Overdraft against property','Explore an overdraft secured by property.']];
