const infoItems=[['kyc','Know Your Customer (KYC)','Guidance about keeping customer information up to date.'],['unclaimed-deposits','Unclaimed deposits','Information to help customers locate inactive or unclaimed deposits.'],['cts-holiday-list','CTS holiday list','Cheque Truncation System holiday information.'],['bank-holiday-list','Bank holiday list','Find the bank holiday information relevant to your area.'],['grievance-redressal','Grievance redressal','Learn how to raise and follow up a service concern.'],['annual-report','Annual report','Annual reporting information and documents.']];
const newsItems=[['community-banking','Community banking, built around people','A closer look at the role of cooperative banking in local communities.','Banking'],['digital-banking','A thoughtful approach to digital banking','How a modern banking experience can put clarity and access first.','Press release'],['customer-first','Putting customer needs at the centre','An editorial on trust, access and everyday banking.','Banking']];
