function ScrollTop(){const {pathname}=useLocation();useEffect(()=>{window.scrollTo({top:0,behavior:'instant'})},[pathname]);return null}
function PageShell({children}){const loc=useLocation();return <AnimatePresence mode="wait"><motion.div key={loc.pathname} className="page" initial={{opacity:0,y:13,filter:'blur(5px)'}} animate={{opacity:1,y:0,filter:'blur(0px)'}} exit={{opacity:0,y:-8,filter:'blur(3px)'}} transition={{duration:.32,ease:[.22,.61,.36,1]}}>{children}</motion.div></AnimatePresence>}
function Footer(){const groups=[['Banking',[['Personal banking','/accounts'],['Savings accounts','/accounts/savings'],['Current accounts','/accounts/current'],['Interest rates','/interest-rates'],['Digital banking preview','/demo/login']]],['Loans',[['All loans','/loans'],['Housing loan','/loans/housing'],['Education loan','/loans/education'],['Gold loan','/loans/gold'],['EMI calculator','/emi-calculator']]],['Savings',[['All deposits','/deposits'],['Fixed deposits','/deposits/short-term'],['Recurring deposits','/deposits/recurring'],['FD calculator','/fd-calculator'],['Interest rates','/interest-rates']]],['Services',[['All services','/services'],['NEFT / RTGS','/services/neft-rtgs'],['SMS alerts','/services/sms-alert'],['Locker services','/services/locker'],['Service charges','/service-charges']]],['About',[['About the bank','/about'],['History','/about/history'],['Management','/about/management'],['Career','/career'],['Annual reports','/about/annual-reports']]],['Resources',[['Downloads and forms','/downloads'],['KYC information','/useful-information/kyc'],['Bank holidays','/useful-information/bank-holiday-list'],['Unclaimed deposits','/useful-information/unclaimed-deposits'],['News and updates','/news']]],['Support',[['Customer support','/customer-support'],['FAQs','/faqs'],['Branch locator','/branches'],['Grievance redressal','/grievance-redressal'],['Report fraud','/report-fraud']]],['Legal',[['Privacy policy','/privacy-policy'],['Terms','/terms'],['Disclaimer','/disclaimer'],['Customer awareness','/customer-awareness'],['Contact us','/contact']]]];return <footer className="footer"><div className="footer-top"><div className="footer-brand"><Link className="brand" to="/"><span className="brand-mark"><Landmark size={21}/></span><span><b>PROGRESSIVE</b><small>CO-OPERATIVE BANK</small></span></Link><p>Personal, community-centred banking information to help you explore your next step.</p><div className="demo-label"><span/> DEMO PREVIEW</div></div>{groups.map(([title,items])=><div className="footer-col" key={title}><h4>{title}</h4>{items.map(([label,path])=><Link to={path} key={label}>{label}</Link>)}</div>)}</div><div className="footer-bottom"><span>© {new Date().getFullYear()} Progressive Co-operative Bank</span><span>Demo information only. Confirm rates, terms, contact details and availability with the bank.</span><Link to="/disclaimer">Disclaimer <ArrowUpRight size={12}/></Link></div></footer>}function Layout(){const loc=useLocation();const demoMode=loc.pathname.startsWith("/demo/");return <><ScrollTop/>{!demoMode&&<Header/>}<PageShell><Routes><Route path="/" element={<Home/>}/><Route path="/demo/login" element={<DemoLogin/>}/><Route path="/demo/dashboard" element={<DemoDashboard/>}/><Route path="/demo-login" element={<DemoLogin/>}/><Route path="/about" element={<About/>}/><Route path="/about/:topic" element={<InstitutionDetail/>}/><Route path="/career" element={<Career/>}/><Route path="/loans" element={<Catalog title="Loans" kicker="Borrow with clarity" intro="Explore lending options designed around different milestones, needs and plans." items={loans} icon={Wallet}/>}/><Route path="/loans/:slug" element={<ProductPage type="loan" items={loans}/>}/><Route path="/deposits" element={<Deposits/>}/><Route path="/deposits/:slug" element={<ProductPage type="deposit" items={deposits}/>}/><Route path="/accounts" element={<Catalog title="Accounts" kicker="Everyday, made considered" intro="Find an account experience that fits the way you save, spend and manage money." items={accounts} icon={PiggyBank}/>}/><Route path="/accounts/:slug" element={<ProductPage type="account" items={accounts}/>}/><Route path="/services" element={<Catalog title="Banking services" kicker="Support for every day" intro="Practical banking services to help you manage the details with confidence." items={services} icon={HeartHandshake}/>}/><Route path="/services/:slug" element={<ProductPage type="service" items={services}/>}/><Route path="/interest-rates" element={<Rates/>}/><Route path="/interest-rates/:kind" element={<RateDetail/>}/><Route path="/emi-calculator" element={<CalculatorPage kind="emi"/>}/><Route path="/fd-calculator" element={<CalculatorPage kind="fd"/>}/><Route path="/branches" element={<Branches/>}/><Route path="/service-charges" element={<Charges/>}/><Route path="/downloads" element={<Downloads/>}/><Route path="/downloads/:slug" element={<DocumentPage/>}/><Route path="/news" element={<News/>}/><Route path="/news/:slug" element={<Article/>}/><Route path="/resources" element={<Useful/>}/><Route path="/resources/:slug" element={<InfoPage/>}/><Route path="/useful-information" element={<Useful/>}/><Route path="/useful-information/:slug" element={<InfoPage/>}/><Route path="/customer-support" element={<SupportHub/>}/><Route path="/faqs" element={<Faqs/>}/><Route path="/grievance-redressal" element={<SupportInfo title="Grievance redressal"/>}/><Route path="/report-fraud" element={<ReportFraud/>}/><Route path="/customer-awareness" element={<CustomerAwareness/>}/><Route path="/contact" element={<Contact/>}/>{['privacy-policy','terms','disclaimer'].map(x=><Route key={x} path={`/${x}`} element={<Policy slug={x}/>}/>)}<Route path="*" element={<NotFound/>}/></Routes></PageShell>{!demoMode&&<Footer/>}</>}
function Crumb({items}){return <div className="crumb"><Link to="/">Home</Link>{items.map(([label,path],i)=><React.Fragment key={label}><ChevronRight size={13}/>{path?<Link to={path}>{label}</Link>:<span>{label}</span>}</React.Fragment>)}</div>}
function Hero({eyebrow,title,subtitle,children,compact=false,visual='arch'}){return <section className={`hero ${compact?'compact':''}`}><div className="hero-grid"><div className="hero-copy"><div className="eyebrow"><span className="eyebrow-dot"/>{eyebrow}</div><h1>{title}</h1>{subtitle&&<p className="hero-subtitle">{subtitle}</p>}{children&&<div className="hero-actions">{children}</div>}</div><div className={`hero-visual ${visual}`} aria-hidden="true"><div className="orb orb-a"/><div className="orb orb-b"/><div className="hero-ring ring-one"/><div className="hero-ring ring-two"/><div className="hero-glow"/><div className="visual-card"><div className="visual-card-top"><span className="mini-brand"><Landmark size={16}/></span><span>PCB <span className="gold-text">Â·</span> BANKING</span><span className="visual-chip"/></div><div className="visual-card-line"/><div className="visual-card-bottom"><span>ROOTED IN COMMUNITY</span><span><ArrowUpRight size={15}/></span></div></div><div className="visual-caption"><Sparkles size={13}/> People-first banking, always</div></div></div></section>}
function SectionHead({kicker,title,copy,link,to}){return <div className="section-head"><div><div className="eyebrow"><span className="eyebrow-dot"/>{kicker}</div><h2>{title}</h2>{copy&&<p>{copy}</p>}</div>{link&&<Link className="text-link" to={to}>{link}<ArrowRight size={15}/></Link>}</div>}
function IconFor({icon:Icon=Landmark,size=23}){return <div className="icon-tile"><Icon size={size} strokeWidth={1.5}/></div>}
function LinkCard({item,base,index=0,icon:Icon=Landmark}){let [slug,title,desc]=item;return <Link className="product-card" to={`${base}/${slug}`}><div className="product-card-top"><IconFor icon={Icon}/><span className="card-index">0{index+1}</span></div><h3>{title}</h3><p>{desc}</p><span className="card-link">Explore more <ArrowUpRight size={15}/></span></Link>}
function CTA({title='Letâ€™s find the right next step',copy='Our team can help you explore the options that fit your needs.',button='Get in touch'}){return <section className="cta-band"><div className="cta-orb"/><div><div className="eyebrow"><span className="eyebrow-dot"/> HERE WHEN YOU NEED US</div><h2>{title}</h2><p>{copy}</p></div><Link to="/contact" className="button button-light">{button}<ArrowRight size={16}/></Link></section>}
function Notice(){return <Link className="notice" to="/disclaimer"><span className="notice-mark"><CircleHelp size={16}/></span><span><b>Important notice</b><small>This is a management demo. Product information and contact details are illustrative or hidden.</small></span><ArrowRight size={15}/></Link>}
function PageIntro({title,kicker,copy,crumb=[]}){return <><div className="page-intro container"><div className="eyebrow"><span className="eyebrow-dot"/>{kicker}</div><h1>{title}</h1>{copy&&<p>{copy}</p>}<Crumb items={crumb.length?crumb:[[title]]}/></div></>}
function Catalog({title,kicker,intro,items,icon:Icon}){const base=title==='Banking services'?'/services':`/${title.toLowerCase()}`;return <><PageIntro title={title} kicker={kicker} copy={intro}/><main className="container content-area"><div className="catalog-intro"><div><h2>Explore your options</h2><p>Choose an option to learn more about its features and next steps.</p></div><span className="count-pill">{String(items.length).padStart(2,'0')} OPTIONS</span></div><div className="product-grid">{items.map((x,i)=><LinkCard key={x[0]} item={x} base={base} index={i} icon={Icon}/>)}</div><div className="info-callout"><ShieldCheck size={20}/><p><b>Need a little guidance?</b><br/>Contact information is hidden in this demo. Start with our contact page to see the support experience.</p><Link to="/contact">Contact us <ArrowRight size={14}/></Link></div><CTA title={`Find your way with ${title.toLowerCase()}.`}/></main></>}
function ProductPage({type,items}){const {slug}=useParams();const product=items.find(x=>x[0]===slug);if(!product)return <NotFound/>;const [,name,desc]=product;let group=type==='loan'?'Loans':type==='deposit'?'Deposits':type==='account'?'Accounts':'Services',base=`/${group.toLowerCase()}`,index=items.findIndex(x=>x[0]===slug);return <><div className="detail-hero"><div className="container"><Crumb items={[[group,base],[name]]}/><div className="detail-layout"><div><div className="eyebrow"><span className="eyebrow-dot"/>{group.toUpperCase()} Â· OPTION {String(index+1).padStart(2,'0')}</div><h1>{name}</h1><p className="detail-lead">{desc}</p><Link className="button button-gold" to="/contact">Enquire about this option <ArrowRight size={16}/></Link></div><div className="detail-emblem"><div className="emblem-ring"><IconFor icon={type==='loan'?Wallet:type==='deposit'?PiggyBank:type==='account'?CreditCard:HeartHandshake} size={31}/></div><span>PERSONAL BANKING</span><div className="emblem-lines"/></div></div></div></div><main className="container detail-content"><div className="detail-columns"><article><div className="eyebrow"><span className="eyebrow-dot"/> GETTING TO KNOW IT</div><h2>A clearer view of<br/><em>{name.toLowerCase()}.</em></h2><p className="section-copy">{desc} This demo presents the product category and a starting point for your questions. Please contact the bank for current terms, eligibility, documentation and availability.</p><Link className="text-link" to="/contact">Ask us a question <ArrowRight size={15}/></Link></article><div className="feature-list">{featureList.map((f,i)=><div className="feature-row" key={f}><span className="feature-num">0{i+1}</span><span>{f}</span><ArrowUpRight size={15}/></div>)}<div className="demo-note"><CircleHelp size={16}/><span>Specific terms and product details are not available in this demo.</span></div></div></div><section className="related"><SectionHead kicker="KEEP EXPLORING" title={`More ${group.toLowerCase()}.`} link={`All ${group.toLowerCase()}`} to={base}/><div className="related-grid">{items.filter(x=>x[0]!==slug).slice(0,3).map((x,i)=><LinkCard key={x[0]} item={x} base={base} index={i}/>)}</div></section><CTA/></main></>}
function Deposits(){return <><PageIntro title="Deposits" kicker="Make room for whatâ€™s next" copy="Explore deposit options for different saving rhythms, timeframes and plans."/><main className="container content-area"><section className="deposit-feature"><div><span className="eyebrow"><span className="eyebrow-dot"/> SAVE WITH PURPOSE</span><h2>Give your plans<br/><em>room to grow.</em></h2><p>Compare the deposit types at a glance. Terms, minimum balances and current rates are available on request.</p><Link className="button button-gold" to="/interest-rates/deposits">View deposit rate information <ArrowRight size={15}/></Link></div><div className="deposit-art"><div className="deposit-sun"/><div className="deposit-stair stair-one"/><div className="deposit-stair stair-two"/><div className="deposit-stair stair-three"/><span>PLAN Â· SAVE Â· GROW</span></div></section><section className="compare-section"><SectionHead kicker="A QUICK COMPARISON" title="Choose a way to save." copy="A simple introduction to each deposit option."/><div className="compare-table"><div className="compare-row compare-head"><span>DEPOSIT TYPE</span><span>INTEREST PAYOUT</span><span>GOOD TO KNOW</span><span/></div>{deposits.map(([slug,title,desc],i)=><Link key={slug} className="compare-row" to={`/deposits/${slug}`}><b>{title}</b><span>{['At maturity','Monthly','Quarterly','At maturity','As agreed'][i]}</span><span>{desc}</span><ArrowUpRight size={15}/></Link>)}</div><p className="table-note"><CircleHelp size={14}/> Product terms, eligibility and current rates are available on request.</p></section><div className="deposit-benefits"><div><IconFor icon={ShieldCheck}/><h3>Plan with clarity</h3><p>Get to know the product before deciding if it suits your goal.</p></div><div><IconFor icon={Clock3}/><h3>Choose your rhythm</h3><p>Explore options with different terms and payout approaches.</p></div><div><IconFor icon={HeartHandshake}/><h3>Get personal support</h3><p>Talk to the bank about terms and availability.</p></div></div><CTA/></main></>}
function About(){const topics=[['History','/about/history'],['Vision and mission','/about/vision-mission'],['Management and board','/about/management'],['Financial highlights','/about/financial-highlights'],['Annual reports','/about/annual-reports'],['Disclosures','/about/disclosures']];return <><PageIntro title="Banking that begins with people." kicker="ABOUT PROGRESSIVE" copy="A cooperative banking perspective, centred on people, trust and community."/><main className="container content-area"><div className="about-opening"><div className="about-monogram">P<span>·</span></div><div><div className="eyebrow"><span className="eyebrow-dot"/> OUR POINT OF VIEW</div><h2>Progressive by name.<br/><em>Progressive in spirit.</em></h2><p className="section-copy">Progressive Co-operative Bank's story is best told through its commitment to the people and communities it serves. This management demo introduces that promise without inventing institutional history.</p></div></div><div className="values-grid">{[['01','People first','We believe a good banking relationship starts with listening and clear guidance.'],['02','Rooted in community','Cooperative banking connects financial services with the communities around them.'],['03','Built on trust','Care, clarity and responsibility belong in every customer interaction.']].map(([n,t,d])=><div className="value-card" key={n}><span>{n}</span><h3>{t}</h3><p>{d}</p></div>)}</div><section className="about-band"><div className="eyebrow"><span className="eyebrow-dot"/> A BANKING PHILOSOPHY</div><h2>Financial confidence<br/>grows through <em>good conversations.</em></h2><p>Explore a banking option, learn about its details, and reach out when you are ready to take the next step.</p><Link to="/services" className="button button-gold">Explore our services <ArrowRight size={15}/></Link></section><div className="about-topic-list">{topics.map(([title,path],i)=><Link to={path} key={path}><span>0{i+1}</span><b>{title}</b><ArrowUpRight size={15}/></Link>)}</div><CTA title="Get to know us, one conversation at a time."/></main></>}
function Career(){return <><PageIntro title="A career with purpose." kicker="CAREERS" copy="Build a meaningful career in cooperative banking and customer service."/><main className="container content-area"><div className="career-panel"><div className="career-icon"><BriefcaseBusiness size={27}/></div><div><span className="eyebrow"><span className="eyebrow-dot"/> OPPORTUNITIES</span><h2>No current openings available in this demo.</h2><p>When career opportunities are available, this page is where youâ€™ll find role information and application guidance.</p><Link to="/contact" className="text-link">Stay in touch <ArrowRight size={15}/></Link></div></div><CTA/></main></>}
function Rates(){const [tab,setTab]=useState('Deposits');const rows=tab==='Deposits'?deposits:loans;return <><PageIntro title="Interest rates" kicker="CLEAR INFORMATION FOR YOUR DECISIONS" copy="Browse rate information by product category. Current rates have not been provided for this demo."/><main className="container content-area"><div className="rate-tabs" role="tablist" aria-label="Rate categories">{['Deposits','Loans'].map(x=><button role="tab" aria-selected={tab===x} className={tab===x?'selected':''} key={x} onClick={()=>setTab(x)}>{x}</button>)}</div><div className="rate-table"><div className="rate-table-head"><span>PRODUCT</span><span>INFORMATION</span><span>CATEGORY</span></div>{rows.map(([slug,title],i)=><Link to={tab==='Deposits'?'/interest-rates/deposits':'/interest-rates/loans'} key={slug}><b>{title}</b><span>Information available in demo.</span><small>{tab.toUpperCase()}</small><ArrowUpRight size={14}/></Link>)}</div><div className="rate-effective"><span>Effective date</span><b>Unavailable in demo</b><span>Official rate sheet</span><Link to="/downloads">View document centre <ArrowUpRight size={13}/></Link></div><p className="table-note"><CircleHelp size={14}/> Confirm applicable rates and terms with the bank.</p><CTA title="Looking for a current rate?" copy="Rate information is available in demo. Contact details are hidden in this showcase version." button="Make an enquiry"/></main></>}function RateDetail(){let {kind}=useParams(),title=kind==='loans'?'Loan rates':'Deposit rates';return <><PageIntro title={title} kicker="INTEREST RATE INFORMATION" copy="Information available in demo." crumb={[["Interest rates","/interest-rates"],[title]]}/><main className="container content-area"><div className="rate-detail"><span className="eyebrow"><span className="eyebrow-dot"/> RATE INFORMATION</span><div className="rate-placeholder">â€”</div><h2>Information available in demo.</h2><p>Current {kind} rates have not been supplied for this management demo. Please contact the bank for the latest applicable rates and terms.</p><Link to="/contact" className="button button-gold">Enquire about rates <ArrowRight size={15}/></Link></div><div className="related"><SectionHead kicker="RELATED" title="Explore more"/><div className="tool-grid"><Link className="tool-card" to={kind==='loans'?'/loans':'/deposits'}><IconFor icon={kind==='loans'?Wallet:PiggyBank}/><div><h3>Explore {kind}</h3><p>Browse available product categories.</p></div><ArrowUpRight className="tool-arrow"/></Link><Link className="tool-card" to={kind==='loans'?'/emi-calculator':'/fd-calculator'}><IconFor icon={Calculator}/><div><h3>Use a calculator</h3><p>Explore a planning tool for your next step.</p></div><ArrowUpRight className="tool-arrow"/></Link></div></div></main></>}
function CalculatorPage({kind}){const emi=kind==='emi',[principal,setPrincipal]=useState(emi?1000000:100000),[rate,setRate]=useState(emi?9:7),[years,setYears]=useState(emi?15:3);const result=useMemo(()=>{let n=years*12;if(emi){let r=rate/1200;return Math.round(principal*r*Math.pow(1+r,n)/(Math.pow(1+r,n)-1))}return Math.round(principal*Math.pow(1+rate/400,4*years))},[principal,rate,years,emi]);return <><PageIntro title={emi?'EMI calculator':'FD calculator'} kicker="TOOLS FOR YOUR PLANS" copy={emi?'Estimate a monthly repayment using an amount, rate and term.':'Explore an indicative maturity value using a deposit amount, rate and term.'}/><main className="container content-area"><div className="calculator-layout"><div className="calculator-form"><div className="eyebrow"><span className="eyebrow-dot"/> YOUR ESTIMATE</div><h2>{emi?'Plan a monthly repayment.':'Plan a fixed deposit.'}</h2><p className="calculator-copy">Adjust the fields to explore an estimate. Values shown are illustrative only.</p><label className="field-label" htmlFor="amount">{emi?'Loan amount':'Deposit amount'} <span>â‚¹</span></label><div className="input-wrap"><span>â‚¹</span><input id="amount" type="number" min="1000" step="1000" value={principal} onChange={e=>setPrincipal(Math.max(1000,Number(e.target.value)))}/></div><input aria-label="Amount slider" className="range" type="range" min="10000" max={emi?10000000:5000000} step="10000" value={Math.min(principal,emi?10000000:5000000)} onChange={e=>setPrincipal(Number(e.target.value))}/><div className="range-limits"><span>â‚¹10,000</span><span>â‚¹{emi?'1,00,00,000':'50,00,000'}</span></div><label className="field-label" htmlFor="rate">{emi?'Interest rate':'Annual interest rate'} <span>% p.a.</span></label><div className="input-wrap"><input id="rate" type="number" min="0.1" max="30" step="0.1" value={rate} onChange={e=>setRate(Number(e.target.value))}/><span>%</span></div><label className="field-label" htmlFor="years">{emi?'Loan term':'Deposit term'} <span>{years} {years===1?'year':'years'}</span></label><input id="years" className="range" type="range" min="1" max={emi?30:10} value={years} onChange={e=>setYears(Number(e.target.value))}/><div className="range-limits"><span>1 year</span><span>{emi?'30':'10'} years</span></div></div><div className="calculator-result"><div className="result-decoration"><div className="result-ring"/><Sparkles size={17}/></div><span className="eyebrow"><span className="eyebrow-dot"/> INDICATIVE ESTIMATE</span><p>{emi?'Estimated monthly payment':'Estimated maturity value'}</p><div className="result-amount">â‚¹{result.toLocaleString('en-IN')}</div><div className="result-divider"/><div className="result-meta"><span>{emi?'Loan amount':'Deposit amount'}<b>â‚¹{principal.toLocaleString('en-IN')}</b></span><span>Illustrative rate<b>{rate}% p.a.</b></span><span>Term<b>{years} {years===1?'year':'years'}</b></span></div><small>This is an estimate for planning purposes. Actual rates, terms, charges, tax treatment and payouts may vary. Contact the bank for details.</small><Link to="/contact" className="button button-gold">Talk to the bank <ArrowRight size={15}/></Link></div></div><div className="calculator-switch"><span>Looking for the other calculator?</span><Link to={emi?'/fd-calculator':'/emi-calculator'}>{emi?'FD calculator':'EMI calculator'} <ArrowRight size={14}/></Link></div></main></>}
